<?php
require_once "config/db.php";$pageTitle='Change password';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$current=$_POST['current_password']??'';$new=$_POST['new_password']??'';$st=$pdo->prepare("SELECT * FROM admins WHERE id=?");$st->execute([$_SESSION['admin_id']]);$admin=$st->fetch();if(!password_verify($current,$admin['password_hash']))$error='Current password is incorrect.';elseif(strlen($new)<8)$error='New password must be at least 8 characters.';else{$st=$pdo->prepare("UPDATE admins SET password_hash=? WHERE id=?");$st->execute([password_hash($new,PASSWORD_DEFAULT),$_SESSION['admin_id']]);$_SESSION['flash']=['type'=>'success','message'=>'Password changed successfully.'];header("Location: dashboard.php");exit;}}
require "includes/header.php";
?><div class="page-intro"><div><h1>Change password</h1><p>Choose a strong password for your administrator account.</p></div></div><section class="panel narrow"><form method="post" class="stack-form"><div class="field"><label>Current password *</label><input type="password" name="current_password" required></div><div class="field"><label>New password *</label><input type="password" name="new_password" minlength="8" required><small>Use at least 8 characters.</small></div><?php if($error): ?><div class="alert error"><?= htmlspecialchars($error) ?></div><?php endif; ?><button class="btn btn-primary">Update password →</button></form></section><?php require "includes/footer.php"; ?>